import{_ as s,o as e,c as n,a2 as t}from"./chunks/framework.BS0bAV7E.js";const g=JSON.parse('{"title":"Shell 基础","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/shell-basics.md","filePath":"zh/manual/shell-basics.md"}'),l={name:"zh/manual/shell-basics.md"};function p(i,a,o,c,d,h){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="shell-基础" tabindex="-1">Shell 基础 <a class="header-anchor" href="#shell-基础" aria-label="Permalink to &quot;Shell 基础&quot;">​</a></h1><p><code>oc&gt;</code> shell 是一个带有 Unix 风格的命令行 - 支持管道、重定向、后台作业、环境变量、别名和小型脚本语言。本文档介绍其实际功能集。</p><h2 id="行编辑" tabindex="-1">行编辑 <a class="header-anchor" href="#行编辑" aria-label="Permalink to &quot;行编辑&quot;">​</a></h2><ul><li>历史记录：上下箭头键浏览历史命令。</li><li>行内编辑：<code>Ctrl+U</code> 删除整行。</li><li>输入源：PS/2 键盘和 COM1 串口输入共享同一队列 - 在 QEMU 中使用 <code>-serial mon:stdio</code> 可通过串口输入。</li></ul><h2 id="命令链与作业" tabindex="-1">命令链与作业 <a class="header-anchor" href="#命令链与作业" aria-label="Permalink to &quot;命令链与作业&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; dhcp &amp;&amp; ping 10.0.2.2      (run ping only if dhcp succeeded)</span></span>
<span class="line"><span>oc&gt; cat a.txt ; cat b.txt      (sequence regardless)</span></span>
<span class="line"><span>oc&gt; health || dmesg            (second only if first failed)</span></span>
<span class="line"><span>oc&gt; ping 10.0.2.2 &amp;            (background job)</span></span>
<span class="line"><span>oc&gt; g6_test &amp;                  (long test in the background)</span></span></code></pre></div><h2 id="管道与重定向" tabindex="-1">管道与重定向 <a class="header-anchor" href="#管道与重定向" aria-label="Permalink to &quot;管道与重定向&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; ls | grep log              (pipe stdout of ls into grep)</span></span>
<span class="line"><span>oc&gt; cat /mnt/f.txt &gt; /tmp/g.txt     (write stdout to a file)</span></span>
<span class="line"><span>oc&gt; cat /mnt/f.txt &gt;&gt; /tmp/g.txt    (append)</span></span>
<span class="line"><span>oc&gt; wget 10.0.2.2 &lt; in.txt     (stdin from a file)</span></span></code></pre></div><h2 id="通配符" tabindex="-1">通配符 <a class="header-anchor" href="#通配符" aria-label="Permalink to &quot;通配符&quot;">​</a></h2><p><code>*</code> 和 <code>?</code> 在命令执行前由 shell 展开：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; ls /mnt/*.txt</span></span>
<span class="line"><span>oc&gt; cat /mnt/report?.txt</span></span></code></pre></div><h2 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; export NAME=value          (set)</span></span>
<span class="line"><span>oc&gt; echo $NAME                 (use - $VAR expands in the line)</span></span>
<span class="line"><span>oc&gt; env                         (list all)</span></span></code></pre></div><p>环境变量存储限制：32 个变量，名称最长 32 字节，值最长 256 字节（<code>shell/shell.h</code>）。</p><h2 id="别名" tabindex="-1">别名 <a class="header-anchor" href="#别名" aria-label="Permalink to &quot;别名&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; alias ll ls -l</span></span>
<span class="line"><span>oc&gt; ll</span></span>
<span class="line"><span>oc&gt; unalias ll</span></span></code></pre></div><p>别名值可包含完整管道 - 最多存储 512 字节，超出则拒绝（不会静默截断）。共 32 个别名槽位。</p><h2 id="当前工作目录" tabindex="-1">当前工作目录 <a class="header-anchor" href="#当前工作目录" aria-label="Permalink to &quot;当前工作目录&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; cd /mnt</span></span>
<span class="line"><span>oc&gt; pwd</span></span></code></pre></div><h2 id="脚本编程" tabindex="-1">脚本编程 <a class="header-anchor" href="#脚本编程" aria-label="Permalink to &quot;脚本编程&quot;">​</a></h2><p>脚本是包含多行命令的文本文件；使用 shell 的脚本运行器执行（具体命令名称请参考你的构建版本中的 <code>help -a</code>）。<code>editor</code> 命令提供一个访客内全屏文本编辑器，用于编写这些脚本。</p><h2 id="命令帮助" tabindex="-1">命令帮助 <a class="header-anchor" href="#命令帮助" aria-label="Permalink to &quot;命令帮助&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; help            (short list, one line per command)</span></span>
<span class="line"><span>oc&gt; help -a         (all 233 commands, alphabetical, with descriptions)</span></span>
<span class="line"><span>oc&gt; help -w         (the same commands grouped by the work package</span></span>
<span class="line"><span>                     that introduced them)</span></span></code></pre></div><p>完整的索引参考（每命令一页）请见 <a href="./commands/">commands/index.md</a>。</p><h2 id="约定" tabindex="-1">约定 <a class="header-anchor" href="#约定" aria-label="Permalink to &quot;约定&quot;">​</a></h2><p>命令可跨版本新增，永不删除；已发布命令的名称和整体行为保持稳定（参见 <a href="./../root/CONTRIBUTING.html">../CONTRIBUTING.md</a>）。命令表容量为 256，目前已注册 233 个。</p>`,26)])])}const u=s(l,[["render",p]]);export{g as __pageData,u as default};
